#!/usr/bin/env bash
# =============================================================================
# InstantGram v1.9.0  -  New logo, username login, forgot password, audio names, clips bar
#   * Your logo is the app icon (adaptive icon too). The app is named "InstantGram".
#   * Login and Create account show the text "InstantGram" instead of a logo.
#   * Log in with your email OR your username.
#   * Forgot password: type an email or username, the link is sent and the screen says where.
#   * The audio (track) name is shown under the username on posts and clips.
#   * Clips progress line: smooth, always on top, drag or tap it to search.
#   * New Firestore rules (username -> email link). Publish them after this update.
# Run from the project root:   bash update_v190_logo_login_audio.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="4fcf31eed64fdba52fde83f5164508bb7e8e0171e728f8945660e8ed896b406b"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/widgets/app_nav_bar.dart ] || { echo "ERROR: v1.8.0 is not installed. Run update_v180_chat_audio.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')
echo "    Dart package: $APP_NAME"

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the updated files..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

echo "==> Registering the logo picture in pubspec.yaml and naming the app..."
python3 - <<'PYX'
import re
p = "pubspec.yaml"
s = open(p).read()
if "assets/logo/" not in s:
    m = re.search(r"^([ \t]*)- assets/music/[ \t]*$", s, re.M)
    if m:
        s = s[:m.end()] + "\n" + m.group(1) + "- assets/logo/" + s[m.end():]
    elif re.search(r"^  assets:[ \t]*$", s, re.M):
        s = re.sub(r"^  assets:[ \t]*$", "  assets:\n    - assets/logo/", s, count=1, flags=re.M)
    else:
        s = s.rstrip("\n") + "\n  assets:\n    - assets/logo/\n"
    open(p, "w").write(s)
    print("    pubspec.yaml: added assets/logo/")
else:
    print("    pubspec.yaml: already has assets/logo/")
m = "android/app/src/main/AndroidManifest.xml"
try:
    t = open(m).read()
    t2 = re.sub(r'android:label="[^"]*"', 'android:label="InstantGram"', t, count=1)
    open(m, "w").write(t2)
    print("    AndroidManifest.xml: app name is InstantGram")
except FileNotFoundError:
    print("    WARNING: AndroidManifest.xml not found, set android:label to InstantGram by hand")
PYX

echo ""
echo "Done. v1.9.0 is in place."
echo ""
echo "IMPORTANT (needed for username login): publish the new Firestore rules."
echo "  Firebase console -> Build -> Firestore Database -> Rules tab"
echo "  Select everything, delete it, paste the full contents of  firebase/firestore.rules , press Publish."
echo ""
echo "Next:"
echo "  flutter clean && flutter pub get && dart analyze && flutter test"
echo '  git add -A && git commit -m "v1.9.0: logo, username login, forgot password, audio names, clips bar" && git push'
exit 0
